const ITEM_BY_ID: ReadonlyMap<string, ItemCatalogEntry> = new Map(
  ITEM_CATALOG.map((item) => [item.id, item]),
)
const ITEM_LABELS = [...new Set(ITEM_CATALOG.map((item) => item.label))]

function itemSprite(id: string): string | null {
  const item = ITEM_BY_ID.get(id)
  return item === undefined
    ? null
    : `${import.meta.env.BASE_URL}items/${item.sprite}${SPRITE_EXT}`
}

export { ITEM_CATALOG, ITEM_LABELS, itemSprite }
export type { ItemCatalogEntry }
